// MainB.java
import java.util.*;

class DaftarNama {
    private List<String> daftar = new ArrayList<>();

    void tambah(String nama) {
        daftar.add(nama);
    }

    int banyak() {
        return daftar.size();
    }

    boolean ada(String nama) {
        return daftar.contains(nama);
    }
}

class Frekuensi {
    static Map<String, Integer> hitung(List<String> kata) {
        Map<String, Integer> hasil = new HashMap<>();
        for (String k : kata) {
            hasil.put(k, hasil.getOrDefault(k, 0) + 1);
        }
        return hasil;
    }
}

public class MainB {
    public static void main(String[] args) {
        DaftarNama d = new DaftarNama();
        d.tambah("Sari");
        d.tambah("Budi");
        System.out.println("Banyak: " + d.banyak());
    }
}

